mapper.select:
SELECT recipe_id as recipeId, owner_user_id as ownerUserId, source_type as sourceType, external_ref_id as externalRefId, title, summary, thumbnail_url as thumbnailUrl, difficulty_cd as difficultyCd, cook_time_min as cookTimeMin, cuisine_style_cd as cuisineStyleCd, is_public as isPublic, is_deleted as isDeleted, view_cnt as viewCnt, like_cnt as likeCnt, report_cnt as reportCnt, created_id as createdId, created_date as createdDate, updated_id as updatedId, updated_date as updatedDate FROM tb_recipe
is_deleted = 'N'
AND recipe_id = #{recipeId}
AND owner_user_id = #{ownerUserId}
AND source_type = #{sourceType}
AND title LIKE '%' || #{title} || '%'
AND difficulty_cd = #{difficultyCd}
AND cook_time_min <= #{cookTimeMin}
AND cuisine_style_cd = #{cuisineStyleCd}
AND is_public = #{isPublic}
ORDER BY created_date DESC, view_cnt DESC
